// Advance watermark after an event with sequence `incoming` applied over `stored`: the higher of the
// two, so an unsequenced event never erases it. See [`edax_event::advance`]. The sequences cross as
// in [`is_stale`].
func Advance(storedPresent bool, stored uint64, incomingPresent bool, incoming uint64) *uint64 {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	var cStoredPresent C.int32_t
	if storedPresent {
		cStoredPresent = 1
	} else {
		cStoredPresent = 0
	}

	cStored := C.uint64_t(uint64(stored))

	var cIncomingPresent C.int32_t
	if incomingPresent {
		cIncomingPresent = 1
	} else {
		cIncomingPresent = 0
	}

	cIncoming := C.uint64_t(uint64(incoming))

	if C.edax_advance_has_result(cStoredPresent, cStored, cIncomingPresent, cIncoming) != 1 {
		return nil
	}
	ptr := C.edax_advance(cStoredPresent, cStored, cIncomingPresent, cIncoming)
	return func() *uint64 { v := uint64(ptr); return &v }()
}

// BackoffMillis wait in milliseconds before retry `attempt` (0-based) under the policy `(base_millis,
// cap_millis)`: full jitter, `entropy` (a random `u64` the host draws per wait) reduced into
// `0 ..= ceiling`. Flat arguments rather than a [`BackoffPolicy`], so a host calls it without
// building a native object per wait. See [`edax_core::backoff_millis`].
func BackoffMillis(baseMillis uint64, capMillis uint64, attempt uint64, entropy uint64) uint64 {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	cBaseMillis := C.uint64_t(uint64(baseMillis))

	cCapMillis := C.uint64_t(uint64(capMillis))

	cAttempt := C.uint64_t(uint64(attempt))

	cEntropy := C.uint64_t(uint64(entropy))

	ptr := C.edax_backoff_millis(cBaseMillis, cCapMillis, cAttempt, cEntropy)
	return uint64(ptr)
}

// CanonicalDecimal canonical text of decimal text (`"9.50"` → `"9.5"`, `"1E+2"` → `"100"`): the one string a host
// writes an exact decimal as, so equality and the command hash see one value. `NaN`, an infinity,
// text that is not a decimal, or one past the digit bound is a `codec:` error. See
// [`edax_cqrs::canonical_decimal`].
func CanonicalDecimal(text string) (string, error) {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	cText := C.CString(text)
	defer C.free(unsafe.Pointer(cText))

	ptr := C.edax_canonical_decimal(cText)
	if err := lastError(); err != nil {
		if ptr != nil {
			C.edax_free_string(ptr)
		}
		return "", err
	}
	defer C.edax_free_string(ptr)
	return C.GoString(ptr), nil
}

// CanonicalJSON kernel's canonical form of a UTF-8 JSON payload: the exact text [`payload_hash_json`] hashes.
