// CheckExtensions refuse an extension key that breaks the rule, as a `codec:` error naming it. A key is 1 to 64
// bytes of `[a-z0-9._-]` and starts with `[a-z0-9]`. See [`edax_event::check_extensions`].
func CheckExtensions(extensions map[string]string) error {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	jsonBytescExtensions, err := json.Marshal(extensions)
	if err != nil {
		return fmt.Errorf("failed to marshal: %w", err)
	}
	// A nil Go slice or map marshals to "null", while a non-nil empty one marshals to
	// "{}" — the form serde_json writes for an empty Rust collection, and the only
	// one the FFI's from_str accepts. Normalise so both spellings of "empty" cross the ABI
	// identically.
	if string(jsonBytescExtensions) == "null" {
		jsonBytescExtensions = []byte("{}")
	}
	cExtensions := C.CString(string(jsonBytescExtensions))
	defer C.free(unsafe.Pointer(cExtensions))

	C.edax_check_extensions(cExtensions)
	return lastError()
}

// CheckProjectionDocument refuse `document_json` as the stored document of projection `id` exactly as the kernel's stores do,
// as a `codec:` error: one that is not a JSON object, holds an integer wider than 64 bits, or is not
// JSON. For a host's own projection store. See [`edax_cqrs::document_json`].
