// CheckSequenceBatch check an append batch against the dense-sequence rule: every event carries a sequence and the
// batch runs `expected + 1, expected + 2, ...` in order. Returns the stream version after the batch.
// `Err` names the 0-based batch index and is a `codec:` (terminal) error. An empty batch passes: it is
// a version check only.
func CheckSequenceBatch(expected uint64, sequences []*uint64) (uint64, error) {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	cExpected := C.uint64_t(uint64(expected))

	jsonBytescSequences, err := json.Marshal(sequences)
	if err != nil {
		return 0, fmt.Errorf("failed to marshal: %w", err)
	}
	// A nil Go slice or map marshals to "null", while a non-nil empty one marshals to
	// "[]" — the form serde_json writes for an empty Rust collection, and the only
	// one the FFI's from_str accepts. Normalise so both spellings of "empty" cross the ABI
	// identically.
	if string(jsonBytescSequences) == "null" {
		jsonBytescSequences = []byte("[]")
	}
	cSequences := C.CString(string(jsonBytescSequences))
	defer C.free(unsafe.Pointer(cSequences))

	ptr := C.edax_check_sequence_batch(cExpected, cSequences)
	if err := lastError(); err != nil {
		return 0, err
	}
	return uint64(ptr), nil
}

