// [`edax_event::is_stale`] and `docs/kernels/event.md`.
//
// Each sequence crosses as a presence bit and a value, read only when present. The C interface
// encodes an absent `Option<u64>` as `u64::MAX`, which is a valid sequence: `staleness.json` pins it.
func IsStale(storedPresent bool, stored uint64, incomingPresent bool, incoming uint64) bool {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	var cStoredPresent C.int32_t
	if storedPresent {
		cStoredPresent = 1
	} else {
		cStoredPresent = 0
	}

	cStored := C.uint64_t(uint64(stored))

	var cIncomingPresent C.int32_t
	if incomingPresent {
		cIncomingPresent = 1
	} else {
		cIncomingPresent = 0
	}

	cIncoming := C.uint64_t(uint64(incoming))

	ptr := C.edax_is_stale(cStoredPresent, cStored, cIncomingPresent, cIncoming)
	return ptr != 0
}

