// KafkaCommandRecord [`kafka_event_record`] for a command: its key is the target aggregate, or else its own id, under
// the same tenancy rule. See [`edax_kafka::record()`].
func KafkaCommandRecord(tenancy string, message CommandMessage, value []byte, contentType string, key *string) (*KafkaRecord, error) {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	cTenancy := C.CString(tenancy)
	defer C.free(unsafe.Pointer(cTenancy))

	jsonBytescMessage, err := json.Marshal(message)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal: %w", err)
	}
	// When the parameter is a nil pointer (Option<&T> on the Rust side), json.Marshal
	// emits "null" which the FFI's _from_json rejects. Substitute "{}" so a default
	// instance is constructed instead — semantically equivalent to None for query types
	// whose fields are all optional with serde(default).
	if string(jsonBytescMessage) == "null" {
		jsonBytescMessage = []byte("{}")
	}
	tmpStrcMessage := C.CString(string(jsonBytescMessage))
	cMessage := C.edax_command_message_from_json(tmpStrcMessage)
	C.free(unsafe.Pointer(tmpStrcMessage))
	if cMessage == 0 {
		return nil, wrapLastError("failed to create command_message")
	}
	defer C.edax_command_message_free(cMessage)

	var cValue *C.uint8_t
	if len(value) > 0 {
		var cValuePinner runtime.Pinner
		cValuePinner.Pin(&value[0])
		defer cValuePinner.Unpin()
		cValue = (*C.uint8_t)(unsafe.Pointer(&value[0]))
	}
	cValueLen := C.uintptr_t(len(value))

	cContentType := C.CString(contentType)
	defer C.free(unsafe.Pointer(cContentType))

	var cKey *C.char
	if key != nil {
		cKey = C.CString(*key)
		defer C.free(unsafe.Pointer(cKey))
	}

	ptr := C.edax_kafka_command_record(cTenancy, cMessage, cValue, cValueLen, cContentType, cKey)
	if err := lastError(); err != nil {
		if ptr != 0 {
			C.edax_kafka_record_free(ptr)
		}
		return nil, err
	}
	defer C.edax_kafka_record_free(ptr)
	jsonPtr := C.edax_kafka_record_to_json(ptr)
	if jsonPtr == nil {
		return nil, fmt.Errorf("failed to convert to JSON")
	}
	defer C.edax_free_string(jsonPtr)
	var result KafkaRecord
	if err := json.Unmarshal([]byte(C.GoString(jsonPtr)), &result); err != nil {
		return nil, fmt.Errorf("failed to unmarshal: %w", err)
	}
	return &result, nil
}

