// OwnCommand `command` as a save of an aggregate of `tenant` sends it: stamped with `tenant` when it names none,
// as it is when it names the same one, and a `codec:` error when it names another. See
// [`edax_event::own_command`].
func OwnCommand(command CommandMessage, tenant *string) (*CommandMessage, error) {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	jsonBytescCommand, err := json.Marshal(command)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal: %w", err)
	}
	// When the parameter is a nil pointer (Option<&T> on the Rust side), json.Marshal
	// emits "null" which the FFI's _from_json rejects. Substitute "{}" so a default
	// instance is constructed instead — semantically equivalent to None for query types
	// whose fields are all optional with serde(default).
	if string(jsonBytescCommand) == "null" {
		jsonBytescCommand = []byte("{}")
	}
	tmpStrcCommand := C.CString(string(jsonBytescCommand))
	cCommand := C.edax_command_message_from_json(tmpStrcCommand)
	C.free(unsafe.Pointer(tmpStrcCommand))
	if cCommand == 0 {
		return nil, wrapLastError("failed to create command_message")
	}
	defer C.edax_command_message_free(cCommand)

	var cTenant *C.char
	if tenant != nil {
		cTenant = C.CString(*tenant)
		defer C.free(unsafe.Pointer(cTenant))
	}

	ptr := C.edax_own_command(cCommand, cTenant)
	if err := lastError(); err != nil {
		if ptr != 0 {
			C.edax_command_message_free(ptr)
		}
		return nil, err
	}
	defer C.edax_command_message_free(ptr)
	jsonPtr := C.edax_command_message_to_json(ptr)
	if jsonPtr == nil {
		return nil, fmt.Errorf("failed to convert to JSON")
	}
	defer C.edax_free_string(jsonPtr)
	var result CommandMessage
	if err := json.Unmarshal([]byte(C.GoString(jsonPtr)), &result); err != nil {
		return nil, fmt.Errorf("failed to unmarshal: %w", err)
	}
	return &result, nil
}

