// record a `bad_handle:` one. See [`edax_redis::settled_value`].
func RedisSettledValue(claim []byte, recordJSON string) ([]byte, error) {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	var cClaim *C.uint8_t
	if len(claim) > 0 {
		var cClaimPinner runtime.Pinner
		cClaimPinner.Pin(&claim[0])
		defer cClaimPinner.Unpin()
		cClaim = (*C.uint8_t)(unsafe.Pointer(&claim[0]))
	}
	cClaimLen := C.uintptr_t(len(claim))

	cRecordJSON := C.CString(recordJSON)
	defer C.free(unsafe.Pointer(cRecordJSON))

	var outPtr *C.uint8_t
	var outLen, outCap C.uintptr_t
	rc := C.edax_redis_settled_value(cClaim, cClaimLen, cRecordJSON, &outPtr, &outLen, &outCap)
	if rc != 0 {
		return nil, lastError()
	}
	if outPtr == nil {
		return nil, lastError()
	}
	defer C.edax_free_bytes(outPtr, outLen, outCap)
	result := C.GoBytes(unsafe.Pointer(outPtr), C.int(outLen))
	return result, nil
}

