// PublishEvent append `message` to the partition of its key: its aggregate, scoped by its tenant where the
// broker's tenancy composes keys. Every group reads it. A tenancy that requires a tenant and a
// message that names none is a `codec:` error, and nothing is appended.
func (h *MemoryBroker) PublishEvent(message EventMessage) error {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	jsonBytescMessage, err := json.Marshal(message)
	if err != nil {
		return fmt.Errorf("failed to marshal: %w", err)
	}
	// When the parameter is a nil pointer (Option<&T> on the Rust side), json.Marshal
	// emits "null" which the FFI's _from_json rejects. Substitute "{}" so a default
	// instance is constructed instead — semantically equivalent to None for query types
	// whose fields are all optional with serde(default).
	if string(jsonBytescMessage) == "null" {
		jsonBytescMessage = []byte("{}")
	}
	tmpStrcMessage := C.CString(string(jsonBytescMessage))
	cMessage := C.edax_event_message_from_json(tmpStrcMessage)
	C.free(unsafe.Pointer(tmpStrcMessage))
	if cMessage == 0 {
		return wrapLastError("failed to create event_message")
	}
	defer C.edax_event_message_free(cMessage)

	C.edax_memory_broker_publish_event(h.ptr, cMessage)
	return lastError()
}

