	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	cTx := C.int64_t(int64(tx))

	cAggregateID := C.CString(aggregateID)
	defer C.free(unsafe.Pointer(cAggregateID))

	cExpectedVersion := C.uint64_t(uint64(expectedVersion))

