// open transaction is refused with a `bad_handle:` (terminal) error.
func (h *MemoryTransactor) Commit(tx int64) error {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	cTx := C.int64_t(int64(tx))

	C.edax_memory_transactor_commit(h.ptr, cTx)
	return lastError()
}

// Rollback drop the transaction's writes and close it. `false` and nothing changes if the token names no
// open transaction: there was nothing to roll back.
func (h *MemoryTransactor) Rollback(tx int64) bool {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	cTx := C.int64_t(int64(tx))

	ptr := C.edax_memory_transactor_rollback(h.ptr, cTx)
	return ptr != 0
}

// OpenCount how many transactions are open on this database. A leak diagnostic: a token that is never
// committed or rolled back conflicts every key it staged for the process lifetime. `u64` rather
// than `usize` because the boundary crosses fixed-width integers only.
func (h *MemoryTransactor) OpenCount() uint64 {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	ptr := C.edax_memory_transactor_open_count(h.ptr)
	return uint64(ptr)
}

