// Book a fetched offset as in flight and return the token that settles it.
//
// Call this before decoding: a payload the host cannot decode still has to be settled, and an
// unbooked offset is either committed past by the next ack or replayed into the same failure
// forever. Booking an offset already in flight takes a fresh token and retires the old one, so a
// redelivered copy settles once.
// A negative offset is a `codec:` error.
func (h *OffsetTracker) Book(topic string, partition int32, offset int64) (int64, error) {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	cTopic := C.CString(topic)
	defer C.free(unsafe.Pointer(cTopic))

	cPartition := C.int32_t(int32(partition))

	cOffset := C.int64_t(int64(offset))

	ptr := C.edax_offset_tracker_book(h.ptr, cTopic, cPartition, cOffset)
	if err := lastError(); err != nil {
		return 0, err
	}
	return int64(ptr), nil
}

// IsLive whether `token` still settles its delivery; a dispatcher skips a delivery whose token a nack
// or a reset retired.
func (h *OffsetTracker) IsLive(token int64) bool {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	cToken := C.int64_t(int64(token))

	ptr := C.edax_offset_tracker_is_live(h.ptr, cToken)
	return ptr != 0
}

// Ack settle `token` as handled: `true` when it settled, `false` when it was stale or unknown. What to
// commit is [`due`](Self::due)'s answer.
func (h *OffsetTracker) Ack(token int64) bool {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	cToken := C.int64_t(int64(token))

	ptr := C.edax_offset_tracker_ack(h.ptr, cToken)
	return ptr != 0
}

// Due every partition whose watermark moved past its last commit, ordered by topic then partition:
// what the host commits in one call, then reports back with [`committed`](Self::committed).
func (h *OffsetTracker) Due() []KafkaDue {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	ptr := C.edax_offset_tracker_due(h.ptr)
	return func() []KafkaDue {
		if ptr == nil {
			return nil
		}
		defer C.edax_free_string(ptr)
		var result []KafkaDue
		if err := json.Unmarshal([]byte(C.GoString(ptr)), &result); err != nil {
			return nil
		}
		return result
	}()
}

