// Attempt attempt a run of `id` of `tenant` is: `max(broker_attempt, recorded) + 1`.
func (h *Retries) Attempt(id string, brokerAttempt uint32, tenant *string) uint32 {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	cid := C.CString(id)
	defer C.free(unsafe.Pointer(cid))

	cBrokerAttempt := C.uint32_t(uint32(brokerAttempt))

	var cTenant *C.char
	if tenant != nil {
		cTenant = C.CString(*tenant)
		defer C.free(unsafe.Pointer(cTenant))
	}

	ptr := C.edax_retries_attempt(h.ptr, cid, cBrokerAttempt, cTenant)
	return uint32(ptr)
}

// Succeeded `id` of `tenant` succeeded: forget its counts.
func (h *Retries) Succeeded(id string, tenant *string) {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	cid := C.CString(id)
	defer C.free(unsafe.Pointer(cid))

	var cTenant *C.char
	if tenant != nil {
		cTenant = C.CString(*tenant)
		defer C.free(unsafe.Pointer(cTenant))
	}

	C.edax_retries_succeeded(h.ptr, cid, cTenant)
}

// Failed `id` of `tenant` failed with a failure carrying the taxonomy code `code`, `None` for one no code
// classifies; the kernel reads the kind off the code ([`edax_event::Failure::of`]). An unknown code
// is a `codec:` error.
func (h *Retries) Failed(id string, brokerAttempt uint32, code *string, tenant *string) (*RetryVerdict, error) {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	cid := C.CString(id)
	defer C.free(unsafe.Pointer(cid))

	cBrokerAttempt := C.uint32_t(uint32(brokerAttempt))

	var cCode *C.char
	if code != nil {
		cCode = C.CString(*code)
		defer C.free(unsafe.Pointer(cCode))
	}

	var cTenant *C.char
	if tenant != nil {
		cTenant = C.CString(*tenant)
		defer C.free(unsafe.Pointer(cTenant))
	}

	ptr := C.edax_retries_failed(h.ptr, cid, cBrokerAttempt, cCode, cTenant)
	if err := lastError(); err != nil {
		return nil, err
	}
	defer C.edax_retry_verdict_free(ptr)
	return func() (*RetryVerdict, error) {
		jsonPtr := C.edax_retry_verdict_to_json(ptr)
		if jsonPtr == nil {
			if err := lastError(); err != nil {
				return nil, err
			}
			return nil, fmt.Errorf("failed to serialise RetryVerdict response: native returned null JSON")
		}
		defer C.edax_free_string(jsonPtr)
		var result RetryVerdict
		if err := json.Unmarshal([]byte(C.GoString(jsonPtr)), &result); err != nil {
			return nil, fmt.Errorf("failed to serialise RetryVerdict response: %w", err)
		}
		return &result, nil
	}()
}

// Sunk sink's answer for the message `id` of `tenant`, dead at `attempt`: `taken`, or refused with a failure
// carrying the taxonomy `code` (`None` for one no code classifies; read only when not `taken`).
// Returns the backoff step to wait before the nack of a refused message, or `None` when nothing
// waits: the sink took it (ack it), or refused it fatally (stop the consumer). An unknown code is a
// `codec:` error. See [`edax_event::Retries::sunk`].
func (h *Retries) Sunk(id string, attempt uint32, taken bool, code *string, tenant *string) (*uint64, error) {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	cid := C.CString(id)
	defer C.free(unsafe.Pointer(cid))

	cAttempt := C.uint32_t(uint32(attempt))

	var cTaken C.int32_t
	if taken {
		cTaken = 1
	} else {
		cTaken = 0
	}

	var cCode *C.char
	if code != nil {
		cCode = C.CString(*code)
		defer C.free(unsafe.Pointer(cCode))
	}

	var cTenant *C.char
	if tenant != nil {
		cTenant = C.CString(*tenant)
		defer C.free(unsafe.Pointer(cTenant))
	}

	if C.edax_retries_sunk_has_result(h.ptr, cid, cAttempt, cTaken, cCode, cTenant) != 1 {
		return nil, lastError()
	}
	ptr := C.edax_retries_sunk(h.ptr, cid, cAttempt, cTaken, cCode, cTenant)
	if err := lastError(); err != nil {
		return nil, err
	}
	return func() *uint64 { v := uint64(ptr); return &v }(), nil
}

